```python
import yfinance as yf
import pandas as pd
import numpy as np

# Define risk tolerance levels (1-5, 1 being most conservative, 5 being most aggressive)
risk_levels = {
    1: "Conservative",
    2: "Moderately Conservative",
    3: "Moderate",
    4: "Moderately Aggressive",
    5: "Aggressive"
}

# Define investment product categories and potential selections.  These need updating frequently.
stock_options = {
    "Tech Growth": ["AAPL", "MSFT", "NVDA", "GOOGL", "AMZN"],
    "Dividend Aristocrats": ["PG", "JNJ", "KO", "PEP", "EMR"],
    "Small Cap Growth": ["AMD", "INTC", "MU", "AVGO", "CSCO"]
}

bond_options = {
    "Treasury": ["US10Y", "US30Y"], # 10yr and 30yr Treasury Yields.  Not actual bond tickers.
    "Corporate": ["LQD", "HYG"] # iShares iBoxx $ Investment Grade Corporate Bond ETF, iShares iBoxx $ High Yield Corporate Bond ETF
}

etf_options = {
    "S&P 500": ["SPY"],
    "Total Stock Market": ["VTI"],
    "International": ["VXUS"]
}


def get_financial_data(tickers):
    """Fetches financial data for given tickers using yfinance."""
    try:
        data = yf.download(tickers, period="1y", interval="1d")
        return data['Close']
    except Exception as e:
        print(f"Error fetching data: {e}")
        return None

def calculate_risk_score(historical_data):
    """Calculates a simplified risk score based on volatility."""
    if historical_data is None:
        return 0  # Or some default value
    returns = historical_data.pct_change().dropna()
    volatility = returns.std()
    return volatility

def generate_recommendations(risk_level):
    """Generates investment recommendations based on risk level."""

    if risk_level not in risk_levels:
        return "Invalid risk level."

    recommendations = {}

    # Stocks - Tailor selection based on risk level.  More aggressive = more growth.
    if risk_level <= 2:
        recommendations["Stocks"] = stock_options["Dividend Aristocrats"][:2]
    elif risk_level == 3:
        recommendations["Stocks"] = stock_options["Dividend Aristocrats"][:1] + stock_options["Small Cap Growth"][:1]
    else:
        recommendations["Stocks"] = stock_options["Small Cap Growth"][:3]

    # Bonds - More conservative = more bonds. Use yield as a proxy for attractiveness
    if risk_level <= 2:
        recommendations["Bonds"] = bond_options["Treasury"][:1]
    elif risk_level == 3:
       recommendations["Bonds"] = bond_options["Treasury"][:1] + bond_options["Corporate"][:1]
    else:
       recommendations["Bonds"] = bond_options["Corporate"][:1]

    # ETFs - Broad market exposure, adaptable to risk profile.
    if risk_level <= 2:
        recommendations["ETFs"] = [etf_options["S&P 500"][0]]
    elif risk_level == 3:
        recommendations["ETFs"] = etf_options["S&P 500"][0] + etf_options["Total Stock Market"][0]
    else:
        recommendations["ETFs"] = etf_options["Total Stock Market"][0] + etf_options["International"][0]


    return recommendations

def main(risk_level):
    """Main function to generate and display recommendations."""
    recommendations = generate_recommendations(risk_level)
    print(f"Investment Recommendations for {risk_levels[risk_level]}:")
    for category, products in recommendations.items():
        print(f"{category}: {', '.join(products)}")



# Example Usage (simulating a user providing a risk level)
user_risk_level = 4
main(user_risk_level)
```
